// ❌ OLD: Attaching an 'unload' event listener disqualifies the entire
// page from being stored in the bfcache in many browsers (especially Chrome/Firefox),
// forcing full-page reloads and slow back/forward navigations.
window.addEventListener('unload', () => {
  navigator.sendBeacon('/analytics', JSON.stringify({ event: 'leave' }));
});

// ✅ NEW: Use 'pagehide' for teardown/beacons and 'pageshow' to handle
// state restoration when the page is unpaused from the bfcache.
window.addEventListener('pagehide', (event) => {
  navigator.sendBeacon('/analytics', JSON.stringify({
    event: 'leave',
    persisted: event.persisted // true if going into bfcache
  }));
});

window.addEventListener('pageshow', (event) => {
  if (event.persisted) {
    console.log('Restored from bfcache! Re-validating stale session...');
    checkUserSession();
  }
});
